begin;
set local lock_timeout='150ms';
set local statement_timeout='5s';
create function public.admin_activity_status(p_status text) returns text language sql immutable set search_path=pg_catalog as $$
 select case when lower(coalesce(p_status,'')) in ('paid','succeeded','complete','completed','held','activated') then 'paid'
 when lower(p_status) in ('partial','partial_paid','partially_paid') then 'partially_paid'
 when lower(p_status) in ('refunded','released') then 'refunded' when lower(p_status) in ('failed','canceled','cancelled') then 'failed'
 when lower(p_status)='waived' then 'waived' else 'pending' end;
$$;
create function public.admin_payment_activity_page(p_filter text default 'all',p_type text default 'all',p_offset integer default 0)
returns jsonb language plpgsql stable set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if auth.uid() is null or not public.is_admin() or not coalesce(public.rentmect_has_permission('tab.payments'),false)
 or not coalesce(public.rentmect_has_permission('reports.financial'),false) then raise exception 'Payment access is required.' using errcode='42501'; end if;
 if p_offset is null or p_offset<0 or p_offset>1000000 or p_filter not in ('all','attention','received','refunds') or p_type not in ('all','payment','rental','deposit','extension','charge','refund','reconciliation') then raise exception 'Invalid payment page.'; end if;
 with raw as materialized (
select 'ledger-'||p.id::text id,p.rental_id::uuid rental_id,case when p.payment_type ilike '%extension%' then 'extension' else 'rental' end::text type,public.admin_activity_status(p.status)::text status_group,coalesce(p.status,'pending')::text display_status,(greatest(0,coalesce(p.total_amount,0)-coalesce(p.deposit_amount,0),coalesce(p.rental_amount,0)+coalesce(p.tax_amount,0)))::numeric amount,(case when public.admin_activity_status(p.status) in ('paid','partially_paid') then greatest(0,coalesce(p.total_amount,0)-coalesce(p.deposit_amount,0),coalesce(p.rental_amount,0)+coalesce(p.tax_amount,0)) else 0 end)::numeric cash_impact,(case when public.admin_activity_status(p.status)='pending' then greatest(0,coalesce(p.total_amount,0)-coalesce(p.deposit_amount,0),coalesce(p.rental_amount,0)+coalesce(p.tax_amount,0)) else 0 end)::numeric outstanding_amount,(coalesce(p.paid_at,p.updated_at,p.created_at))::timestamptz event_at,(p.payment_received_date)::date received_date,(p.payment_received_time)::time received_time,(concat_ws(' • ',p.payment_type,p.failure_reason))::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rental_payments p where greatest(0,coalesce(p.total_amount,0)-coalesce(p.deposit_amount,0),coalesce(p.rental_amount,0)+coalesce(p.tax_amount,0))>0 or coalesce(p.deposit_amount,0)<=0
 union all
select 'ledger-deposit-'||p.id::text id,p.rental_id::uuid rental_id,'deposit'::text type,case when (public.admin_activity_status(p.status) in ('paid','partially_paid') or p.deposit_status in ('held','release_pending','released')) then 'paid' else public.admin_activity_status(coalesce(p.deposit_status,p.status)) end::text status_group,coalesce(p.deposit_status,p.status)::text display_status,(p.deposit_amount)::numeric amount,(case when (public.admin_activity_status(p.status) in ('paid','partially_paid') or p.deposit_status in ('held','release_pending','released')) then p.deposit_amount else 0 end)::numeric cash_impact,(case when (public.admin_activity_status(p.status) in ('paid','partially_paid') or p.deposit_status in ('held','release_pending','released')) then 0 else p.deposit_amount end)::numeric outstanding_amount,(coalesce(p.paid_at,p.updated_at,p.created_at))::timestamptz event_at,(p.payment_received_date)::date received_date,(p.payment_received_time)::time received_time,(p.payment_type)::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rental_payments p where p.deposit_amount>0 and not exists(select 1 from public.rental_deposit_allocations a where a.holder_rental_id=p.rental_id)
 union all
select 'ledger-refund-'||p.id::text id,p.rental_id::uuid rental_id,'refund'::text type,'refunded'::text status_group,'refunded'::text display_status,(-p.refunded_amount)::numeric amount,(-p.refunded_amount)::numeric cash_impact,(0)::numeric outstanding_amount,(p.deposit_refunded_at)::timestamptz event_at,(null)::date received_date,(null)::time received_time,('Payment refund')::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rental_payments p where p.refunded_amount>0 and not exists(select 1 from public.rental_deposit_allocations a where a.holder_rental_id=p.rental_id)
 union all
select 'rental-payment-refund-'||p.id::text id,p.rental_id::uuid rental_id,'refund'::text type,case when p.status='succeeded' then 'refunded' when p.status in ('failed','cancelled') then 'failed' else 'pending' end::text status_group,p.status::text display_status,(-p.amount)::numeric amount,(case when p.status='succeeded' then -p.amount else 0 end)::numeric cash_impact,(0)::numeric outstanding_amount,(p.created_at)::timestamptz event_at,(null)::date received_date,(null)::time received_time,(p.reason)::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(p.stripe_refund_id)::text refund_id from public.rental_payment_refunds p where true
 union all
select 'rental-'||r.id::text id,r.id::uuid rental_id,'rental'::text type,case when r.payment_status='paid' then 'paid' when r.payment_status in ('partial','partial_paid','partially_paid') then 'partially_paid' else 'pending' end::text status_group,coalesce(r.payment_status,'pending')::text display_status,(case when r.payment_status in ('partial','partial_paid','partially_paid') and r.payment_amount_cents>0 then r.payment_amount_cents/100.0 else (coalesce(r.rental_total,0)+coalesce(r.service_fee_total,0)+coalesce(r.tax_amount,0)) end)::numeric amount,(case when r.payment_status='paid' then (coalesce(r.rental_total,0)+coalesce(r.service_fee_total,0)+coalesce(r.tax_amount,0)) when r.payment_status in ('partial','partial_paid','partially_paid') then least(coalesce(r.payment_amount_cents,0)/100.0,(coalesce(r.rental_total,0)+coalesce(r.service_fee_total,0)+coalesce(r.tax_amount,0))) else 0 end)::numeric cash_impact,(greatest(0,(coalesce(r.rental_total,0)+coalesce(r.service_fee_total,0)+coalesce(r.tax_amount,0))-(case when r.payment_status='paid' then (coalesce(r.rental_total,0)+coalesce(r.service_fee_total,0)+coalesce(r.tax_amount,0)) when r.payment_status in ('partial','partial_paid','partially_paid') then least(coalesce(r.payment_amount_cents,0)/100.0,(coalesce(r.rental_total,0)+coalesce(r.service_fee_total,0)+coalesce(r.tax_amount,0))) else 0 end)))::numeric outstanding_amount,(coalesce(r.paid_at,r.updated_at,r.created_at))::timestamptz event_at,(r.payment_received_date)::date received_date,(r.payment_received_time)::time received_time,('Rental balance')::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rentals r where r.status<>'cancelled' and not exists(select 1 from public.rental_payments p where p.rental_id=r.id) and not exists(select 1 from public.rental_charge_items c where c.rental_id=r.id and c.charge_type='rental_amendment')
 union all
select 'deposit-'||r.id::text id,r.id::uuid rental_id,'deposit'::text type,case when r.deposit_status in ('held','adjustment_refund_due','release_pending','released','transferred') then 'paid' else public.admin_activity_status(r.deposit_status) end::text status_group,r.deposit_status::text display_status,(r.security_deposit)::numeric amount,(case when r.deposit_status in ('held','adjustment_refund_due','release_pending','released','transferred') then r.security_deposit else 0 end)::numeric cash_impact,(case when r.deposit_status in ('held','adjustment_refund_due','release_pending','released','transferred') then 0 else r.security_deposit end)::numeric outstanding_amount,(coalesce(r.paid_at,r.updated_at,r.created_at))::timestamptz event_at,(null)::date received_date,(null)::time received_time,(r.deposit_release_error)::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rentals r where r.status<>'cancelled' and not exists(select 1 from public.rental_payments p where p.rental_id=r.id) and not exists(select 1 from public.rental_charge_items c where c.rental_id=r.id and c.charge_type='rental_amendment') and r.security_deposit>0 and not exists(select 1 from public.rental_deposit_allocations a where a.holder_rental_id=r.id)
 union all
select 'allocation-'||a.id::text id,a.holder_rental_id::uuid rental_id,'deposit'::text type,case when a.status='failed' then 'failed' else 'paid' end::text status_group,a.status::text display_status,(a.amount_held)::numeric amount,(case when a.flex_payment_receipt_id is null then a.amount_held else 0 end)::numeric cash_impact,(0)::numeric outstanding_amount,(a.created_at)::timestamptz event_at,(null)::date received_date,(null)::time received_time,(concat_ws(' • ',a.source_kind,a.last_error))::text detail,(null)::text funding_kind,(a.flex_payment_receipt_id is not null)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rental_deposit_allocations a where true
 union all
select 'external-refund-'||a.id::text id,a.rental_id::uuid rental_id,'refund'::text type,'refunded'::text status_group,'refunded'::text display_status,(-a.amount)::numeric amount,(-a.amount)::numeric cash_impact,(0)::numeric outstanding_amount,(a.created_at)::timestamptz event_at,(null)::date received_date,(null)::time received_time,(a.reason)::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rental_external_payment_actions a where a.action_type='refund' and not exists(select 1 from public.rental_charge_items c where c.id=a.payment_charge_id and c.flex_payment_receipt_id is not null)
 union all
select 'deposit-refund-'||a.id::text id,a.holder_rental_id::uuid rental_id,'refund'::text type,case when greatest(0,coalesce(a.amount_released,0)-coalesce(a.external_receipt_refunded_amount,0))>0 then 'refunded' when a.status='release_pending' then 'pending' else 'failed' end::text status_group,case when greatest(0,coalesce(a.amount_released,0)-coalesce(a.external_receipt_refunded_amount,0))>0 then 'refunded' when a.status='release_pending' then 'pending' else 'failed' end::text display_status,(-(case when greatest(0,coalesce(a.amount_released,0)-coalesce(a.external_receipt_refunded_amount,0))>0 then greatest(0,coalesce(a.amount_released,0)-coalesce(a.external_receipt_refunded_amount,0)) else coalesce(a.refund_reserved_amount,coalesce(a.amount_held,0)-coalesce(a.amount_applied,0)) end))::numeric amount,(case when greatest(0,coalesce(a.amount_released,0)-coalesce(a.external_receipt_refunded_amount,0))>0 then -(greatest(0,coalesce(a.amount_released,0)-coalesce(a.external_receipt_refunded_amount,0))) else 0 end)::numeric cash_impact,(0)::numeric outstanding_amount,(case when greatest(0,coalesce(a.amount_released,0)-coalesce(a.external_receipt_refunded_amount,0))>0 then a.refund_completed_at else a.refund_requested_at end)::timestamptz event_at,(null)::date received_date,(null)::time received_time,(concat_ws(' • ',a.payment_provider,a.external_return_reference,a.external_return_note,a.refund_id))::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(a.refund_id)::text refund_id from public.rental_deposit_allocations a where greatest(0,coalesce(a.amount_released,0)-coalesce(a.external_receipt_refunded_amount,0))>0 or a.refund_id is not null or a.status in ('release_pending','failed')
 union all
select 'deposit-refund-'||r.id::text id,r.id::uuid rental_id,'refund'::text type,case when (r.deposit_refund_id is not null or r.deposit_released_at is not null) and r.deposit_status='released' then 'refunded' when (r.deposit_refund_id is not null or r.deposit_released_at is not null) and r.deposit_status='release_pending' then 'pending' else 'failed' end::text status_group,case when (r.deposit_refund_id is not null or r.deposit_released_at is not null) and r.deposit_status='released' then 'refunded' when (r.deposit_refund_id is not null or r.deposit_released_at is not null) and r.deposit_status='release_pending' then 'pending' else 'failed' end::text display_status,(-(coalesce(nullif(greatest(0,coalesce(r.deposit_released_amount,0)-coalesce((select sum(a.deposit_amount_returned) from public.rental_external_payment_actions a where a.rental_id=r.id and a.action_type='refund'),0)),0),r.security_deposit,0)))::numeric amount,(case when (r.deposit_refund_id is not null or r.deposit_released_at is not null) and r.deposit_status='released' then -(coalesce(nullif(greatest(0,coalesce(r.deposit_released_amount,0)-coalesce((select sum(a.deposit_amount_returned) from public.rental_external_payment_actions a where a.rental_id=r.id and a.action_type='refund'),0)),0),r.security_deposit,0)) else 0 end)::numeric cash_impact,(0)::numeric outstanding_amount,(coalesce(r.deposit_released_at,case when r.deposit_refund_id is not null then r.deposit_release_attempted_at end))::timestamptz event_at,(null)::date received_date,(null)::time received_time,(case when (r.deposit_refund_id is not null or r.deposit_released_at is not null) then 'Deposit refund' else 'Historical deposit total; refund transaction not verified' end)::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(r.deposit_refund_id)::text refund_id from public.rentals r where not exists(select 1 from public.rental_deposit_allocations a where a.holder_rental_id=r.id) and (greatest(0,coalesce(r.deposit_released_amount,0)-coalesce((select sum(a.deposit_amount_returned) from public.rental_external_payment_actions a where a.rental_id=r.id and a.action_type='refund'),0))>0.005 or r.deposit_refund_id is not null)
 union all
select 'extension-'||e.id::text id,e.rental_id::uuid rental_id,'extension'::text type,case when e.status='activated' then 'paid' else public.admin_activity_status(e.payment_status) end::text status_group,coalesce(e.payment_status,e.status)::text display_status,(case when e.payment_status in ('partial','partial_paid','partially_paid') and e.payment_amount_cents>0 then e.payment_amount_cents/100.0 else coalesce(e.extension_total_amount,0) end)::numeric amount,(case when case when e.status='activated' then 'paid' else public.admin_activity_status(e.payment_status) end='paid' then coalesce(nullif(e.payment_amount_cents,0)/100.0,e.extension_total_amount,0) when case when e.status='activated' then 'paid' else public.admin_activity_status(e.payment_status) end='partially_paid' then coalesce(e.payment_amount_cents,0)/100.0 else 0 end)::numeric cash_impact,(greatest(0,coalesce(e.extension_total_amount,0)-(case when case when e.status='activated' then 'paid' else public.admin_activity_status(e.payment_status) end='paid' then coalesce(nullif(e.payment_amount_cents,0)/100.0,e.extension_total_amount,0) when case when e.status='activated' then 'paid' else public.admin_activity_status(e.payment_status) end='partially_paid' then coalesce(e.payment_amount_cents,0)/100.0 else 0 end)))::numeric outstanding_amount,(coalesce(e.paid_at,e.updated_at,e.created_at))::timestamptz event_at,(e.payment_received_date)::date received_date,(e.payment_received_time)::time received_time,(case when e.request_kind='switch_car_continuation' then 'Vehicle switch' else 'Extension' end)::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rental_extension_requests e where (e.status in ('approved_pending_payment','activated') or e.payment_status in ('pending','paid')) and not exists(select 1 from public.rental_payments p where p.stripe_payment_intent_id=e.stripe_payment_intent_id or p.stripe_checkout_session_id=e.stripe_checkout_session_id)
 union all
select 'charge-'||c.id::text id,c.rental_id::uuid rental_id,'charge'::text type,public.admin_activity_status(c.status)::text status_group,c.status::text display_status,(case when c.status in ('partial','partial_paid','partially_paid') and c.payment_amount_cents>0 then c.payment_amount_cents/100.0 else coalesce(c.total_amount,0) end)::numeric amount,(case when c.allocation_managed or c.payment_provider='deposit' then 0 else case when public.admin_activity_status(c.status)='paid' then coalesce(nullif(c.payment_amount_cents,0)/100.0,c.total_amount,0) when public.admin_activity_status(c.status)='partially_paid' then coalesce(c.payment_amount_cents,0)/100.0 else 0 end end)::numeric cash_impact,(case when c.allocation_managed then case when c.status in ('paid','waived','cancelled') then 0 else greatest(0,coalesce(c.total_amount,0)-(coalesce(c.allocated_payment_cents,0)+coalesce(c.allocated_waiver_cents,0)+coalesce(c.allocated_deposit_cents,0))/100.0) end when public.admin_activity_status(c.status) in ('pending','failed') then greatest(0,coalesce(c.total_amount,0)-(case when public.admin_activity_status(c.status)='paid' then coalesce(nullif(c.payment_amount_cents,0)/100.0,c.total_amount,0) when public.admin_activity_status(c.status)='partially_paid' then coalesce(c.payment_amount_cents,0)/100.0 else 0 end)) else 0 end)::numeric outstanding_amount,(coalesce(c.paid_at,c.updated_at,c.created_at))::timestamptz event_at,(c.payment_received_date)::date received_date,(c.payment_received_time)::time received_time,(c.name)::text detail,(null)::text funding_kind,(coalesce(c.allocation_managed,false))::boolean allocation_managed,(case when c.status='paid' then coalesce(c.payment_receipt_id,c.external_toll_receipt_id)::text end)::text receipt_id,(null)::text refund_id from public.rental_charge_items c where not coalesce(c.included_in_initial_payment,false) and c.charge_type<>'rental_installment' and c.flex_payment_receipt_id is null
 union all
select 'stripe-reconciliation-'||i.id::text id,i.rental_id::uuid rental_id,'reconciliation'::text type,case when i.status='resolved' then 'paid' when i.status='refunded' then 'refunded' when i.status='processing' then 'pending' else 'failed' end::text status_group,case when i.status='open' then 'action required' else i.status end::text display_status,(coalesce(i.amount,0))::numeric amount,(0)::numeric cash_impact,(0)::numeric outstanding_amount,(coalesce(i.updated_at,i.created_at))::timestamptz event_at,(null)::date received_date,(null)::time received_time,(concat_ws(' • ',i.issue_type,i.error_message))::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(i.refund_id)::text refund_id from public.stripe_reconciliation_issues i where true
 union all
select 'extra-refund-'||c.id::text id,c.rental_id::uuid rental_id,'refund'::text type,'refunded'::text status_group,'refunded'::text display_status,(-c.external_refunded_amount)::numeric amount,(-c.external_refunded_amount)::numeric cash_impact,(0)::numeric outstanding_amount,(c.external_refunded_at)::timestamptz event_at,(null)::date received_date,(null)::time received_time,(c.name)::text detail,(null)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.rental_charge_items c where c.external_refunded_amount>0
 union all
select 'flex-cash-'||p.id::text id,p.rental_id::uuid rental_id,'payment'::text type,'paid'::text status_group,'paid'::text display_status,(p.amount_cents/100.0)::numeric amount,(case when p.funding_kind='credit' then 0 else p.amount_cents/100.0 end)::numeric cash_impact,(0)::numeric outstanding_amount,(p.posted_at)::timestamptz event_at,(p.received_date)::date received_date,(p.received_time)::time received_time,(case when p.funding_kind='credit' then 'Customer credit applied; no new money received' else 'Allocated payment' end)::text detail,(p.funding_kind)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.external_payment_receipts p where p.allocation_version=2 and p.status in ('posted','refunded')
 union all
select 'flex-cash-refund-'||p.id::text id,p.rental_id::uuid rental_id,'refund'::text type,'refunded'::text status_group,'refunded'::text display_status,(-p.amount_cents/100.0)::numeric amount,(case when p.funding_kind='credit' then 0 else -p.amount_cents/100.0 end)::numeric cash_impact,(0)::numeric outstanding_amount,(p.refunded_at)::timestamptz event_at,(null)::date received_date,(null)::time received_time,(case when p.funding_kind='credit' then 'Customer credit applied; no new money received' else 'Allocated payment' end)::text detail,(p.funding_kind)::text funding_kind,(false)::boolean allocation_managed,(null)::text receipt_id,(null)::text refund_id from public.external_payment_receipts p where p.allocation_version=2 and p.status='refunded'
 ), grouped as materialized (
 select coalesce('receipt-'||receipt_id,id) id,rental_id,case when receipt_id is not null then 'payment' else type end type,status_group,display_status,
 sum(amount) amount,sum(cash_impact) cash_impact,sum(outstanding_amount) outstanding_amount,max(event_at) event_at,max(received_date) received_date,max(received_time) received_time,
 string_agg(detail,' • ') detail,funding_kind,allocation_managed,max(refund_id) refund_id
 from raw group by coalesce('receipt-'||receipt_id,id),rental_id,case when receipt_id is not null then 'payment' else type end,status_group,display_status,funding_kind,allocation_managed
 ), page as materialized (
 select * from grouped where (p_type='all' or type=p_type) and (p_filter='all'
 or p_filter='attention' and status_group in ('pending','partially_paid','failed')
 or p_filter='received' and status_group='paid' and funding_kind is distinct from 'credit' and not allocation_managed
 or p_filter='refunds' and (status_group='refunded' or type='refund'))
 order by event_at desc nulls last,id desc offset p_offset limit 51
 ), visible as (select * from page order by event_at desc nulls last,id desc limit 50), rows as (
 select jsonb_build_object('id',e.id,'rentalId',e.rental_id,'customer',coalesce(p.full_name,r.customer_name_snapshot,to_jsonb(r)->>'user_email',r.customer_email_snapshot,'Client'),
 'vehicle',coalesce(v.name,'Vehicle'),'type',e.type,'statusGroup',e.status_group,'displayStatus',e.display_status,'amount',e.amount,
 'cashImpact',e.cash_impact,'outstandingAmount',e.outstanding_amount,'date',e.event_at,'receivedDate',e.received_date,'receivedTime',e.received_time,
 'detail',e.detail,'fundingKind',e.funding_kind,'allocationManaged',e.allocation_managed,'refundId',e.refund_id) value,e.event_at,e.id
 from visible e left join public.rentals r on r.id=e.rental_id left join public.profiles p on p.id=r.user_id left join public.vehicles v on v.id=r.vehicle_id
 ) select jsonb_build_object('rows',coalesce((select jsonb_agg(value order by event_at desc nulls last,id desc) from rows),'[]'::jsonb),
 'has_more',(select count(*)>50 from page),
 'totals',jsonb_build_object('collected',(select coalesce(sum(greatest(0,cash_impact)),0) from grouped),
 'refunded',(select coalesce(sum(greatest(0,-cash_impact)),0) from grouped),
 'outstanding',(select coalesce(sum(greatest(0,outstanding_amount)),0) from grouped),
 'deposits',(select coalesce(sum(deposit_held_amount),0) from public.rentals where deposit_status in ('held','adjustment_refund_due','release_pending'))),
 'reconciliation_count',(select count(*) from grouped where type='reconciliation' and status_group in ('pending','failed'))) into result;
 return result;
end $$;
revoke all on function public.admin_payment_activity_page(text,text,integer) from public,anon;
grant execute on function public.admin_payment_activity_page(text,text,integer) to authenticated;
notify pgrst,'reload schema';
commit;
